Ext._define('planning.hiring.minute.MinuteGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'planning.hiring.minute.MinuteWindow',
    configOrderToolBar: ['add', 'edit', 'finalize', '-', 'report', '-', 'export', '-', 'search', 'active', '-', 'all'],

    getColumnModel: function () {
        if (!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    { header: 'Status', dataIndex: 'icons', sortable: false, renderer: core.rendererIconGrid, menuDisabled: true, width: 90 },
                    { header: 'Número da Ata', dataIndex: 'number', width: 90 },
                    { header: 'Objeto da Ata', dataIndex: 'minute_object', id: 'autoExpandColumn' },
                    { header: 'Fiscal', dataIndex: 'main_minutesupervisors', sortable: true, width: 95 },
                    { header: 'Processo', dataIndex: 'process_number', width: 160 },
                    { header: 'Vigência', dataIndex: 'end_validity', renderer: Ext.util.Format.dateRenderer('d/m/Y') },


                ]
            );

        return this._columnModel;
    },

    updateItem: function (record) {
        var minute = this.getSelectionModel().getSelected().get('pk');

        this.setParam('minute', minute);
        planning.hiring.minute.MinuteGrid.superclass.updateItem.call(this, record);
    },

    execMinuteAction: function (num) {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            var wnd = Ext._create('planning.hiring.minuteaction.MinuteActionWindow', {
                params: {
                    action: num,
                    minute: selected.get('pk'),
                    user: 845,
                },
                callback: {
                    success: {
                        scope: this,
                        fn: function (args) {
                            this.getStore().reload();
                        }
                    }
                },
                action: 'create',
            });

            wnd.show();
        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione uma ata para finalizar.'
            });
        }
    },

    execFinalizeAction: function () {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            var title = 'Finalizando atas...';
            var msg = 'Informe uma observação para finalizar a(s) ata(s)?';
            var scope = this;
            var multiline = true;
            var fn_callback = function (btn, text) {
                if (btn == 'cancel') return;

                Ext.Ajax.request({
                    url: core.callAction('PHMMinuteAction', 'finalize_minute_action'),
                    scope: this,
                    params: {
                        minutes: this.getSelectionModel().getSelections().map(
                            function (record) {
                                return record.get('pk')
                            }
                        ).join(),
                        observation: text ? text : ''
                    },
                    success: function (request) {
                        var rst = Ext.decode(request.responseText);

                        if (rst.success)
                            this.getStore().reload();
                        else
                            Ext.Msg.show({
                                title: 'Finalizando ata',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    }
                });
            };

            Ext.Msg.prompt(title, msg, fn_callback, scope, multiline);

        } else {
            Ext.Msg.show({
                title: 'Atenção',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione uma ata para finalizar.'
            });
        }
    },

    getFinalizeAction: function () {
        if (!this._finalizeAction)
            this._finalizeAction = Ext._create('Ext.Button', {
                text: 'Finalizar',
                iconCls: 'icon-agree icon-agree-delete',
                scope: this,
                handler: function () {
                    this.execFinalizeAction()
                }
            });

        return this._finalizeAction;
    },

    getReportAction: function () {
        if (!this._reportAction)
            this._reportAction = Ext._create('Ext.Button', {
                text: 'Relatórios',
                iconCls: 'icon-agree icon-agree-application-pdf',
                scope: this,
                menu: [
                    {
                        text: 'Listagem de Atas',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.MinuteListReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Atas por Fiscal',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.MinuteListBySupervisorReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Pagamentos por Ata',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.SolicitationListPaymentByMinuteReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Pedidos',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.SolicitationListReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Pedidos por Ata',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.SolicitationListByMinuteReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Pedidos por Objeto da Ata',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.SolicitationListByObjectMinuteReport').show();
                        }
                    },
                    {
                        text: 'Listagem de Fiscais de Atas',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: function () {
                            Ext._create('planning.hiring.minutereport.ReportMinuteSupervisor').show();
                        }
                    },
                ]
            });

        return this._reportAction;
    },

    getExportAction: function () {
        if (!this._exportAction) {
            this._exportAction = Ext._create('Ext.Button', {
                text: 'Exportar XLS',
                iconCls: 'icon-core icon-core-csv',
                scope: this,
                handler: function () {
                    Ext._create('planning.hiring.minutereport.MinuteExportXLS').show();
                }
            });
        }

        return this._exportAction;
    },

    getActiveAction: function () {
        if (!this._activeAction)
            this._activeAction = Ext._create('Ext.form.Checkbox', {
                boxLabel: 'Incluir Inativos',
                scope: this,
                handler: function (c, v) {
                    var store = this.getStore();
                    if (!v) {
                        this.disable();
                        this.getAllAction().enable()
                        store.removeAll();
                        this.setFilterProperty('status__in', [1,], 1000);
                        this.enable();
                    }
                    else {
                        this.disable();
                        this.getAllAction().disable()
                        store.removeAll();
                        this.setFilterProperty('status__in', [1, 2, 3, 4, 5, 6], 1000);
                        this.enable();
                    }
                }
            });

        return this._activeAction;
    },

    /* Valor -1 não existe em MINUTE_STATUS. O motivo é validar a request no método get_query */
    getAllAction: function () {
        if (!this._allAction)
            this._allAction = Ext._create('Ext.form.Checkbox', {
                boxLabel: 'Todas Atas',
                scope: this,
                handler: function (c, v) {
                    var store = this.getStore();
                    if (v) {
                        this.disable()
                        this.getActiveAction().disable()
                        store.removeAll();
                        this.setFilterProperty('status__in', [-1,1,2,3,4,5,6], 1000);
                        this.enable();
                    }else{
                        this.disable()
                        this.getActiveAction().enable()
                        store.removeAll();
                        this.setFilterProperty('status__in', [1,], 1000);
                        this.enable();
                    }
                }
            });

        return this._allAction;
    },
    
});

core.RestfulGrid.register(
    'planning.hiring.minute.MinuteRestful',
    'planning.hiring.minute.MinuteGrid'
);
